};


/**
 * @method
 * @name scwin.registerProcess
 * @author Inswave
 * @date 2026. 09. 29
 * @param applNo docNo formCd formVer wrtrptMaindocTpCd method exmptObjDisclsYn
 * @returns
 * @hidden N
*/
scwin.registerProcess = async function (applNo, docNo, formCd, formVer, wrtrptMaindocTpCd, method, exmptObjDisclsYn) {
    /* sdd-asis-lifecycle:begin fn_registerProcess — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_documentWriteReq').set('applNo', applNo);
    if (applNo.length == 14) {
        await scwin.documentWrite(exmptObjDisclsYn);
    } else {
        await scwin.registerMessage('문서불러오기에 실패하였습니다. 잠시후 다시 해주시기 바랍니다.');
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.registerMessage
 * @author Inswave
 * @date 2026. 09. 29
